def cal_sum(n):
    """Write a function to calculate the sum of perrin numbers."""
    if n < 0:
        return 0
    perrin = [3, 0, 2]
    for i in range(3, n + 1):
        perrin.append(perrin[i - 2] + perrin[i - 3])
    return sum(perrin[: n + 1])
